import React, { createContext, useState, useEffect } from "react";
import axios from "../utils/axiosFlask";

const GeneralContext = createContext();

export const GeneralContextProvider = ({ children }) => {
  const [watchlist, setWatchlist] = useState([]);
  const [buyWindowOpen, setBuyWindowOpen] = useState(false);
  const [buyWindowData, setBuyWindowData] = useState({
    symbol: null,
    mode: "BUY",
  });

  const refreshWatchlist = async () => {
    try {
      const response = await axios.get("/api/watchlist");
      setWatchlist(response.data.stocks || []);
    } catch (error) {
      console.error("Failed to refresh watchlist:", error);
      setWatchlist([]);
    }
  };

  useEffect(() => {
    refreshWatchlist();
  }, []);

  const openBuyWindow = (symbol, mode) => {
    setBuyWindowData({ symbol, mode });
    setBuyWindowOpen(true);
  };

  const closeBuyWindow = () => {
    setBuyWindowOpen(false);
    setBuyWindowData({ symbol: null, mode: "BUY" });
  };

  return (
    <GeneralContext.Provider
      value={{
        watchlist,
        refreshWatchlist,
        openBuyWindow,
        closeBuyWindow,
        buyWindowOpen,
        buyWindowData,
      }}>
      {children}
    </GeneralContext.Provider>
  );
};

export default GeneralContext;
